<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';const router=useRouter();const me=ref<any>({});onMounted(async()=>me.value=await (await fetch('/api/v1/me')).json());const logout=async()=>{await fetch('/api/v1/auth/logout',{method:'POST'});router.push('/login')}</script>
<template><div class="hero"><div><p class="kicker">ACCOUNT</p><h1>Settings</h1><p class="muted">Manage this local StackHost administrator.</p></div></div><div class="status"><div><strong>{{me.name}}</strong><p>{{me.email}} · {{me.role}}</p></div></div><button class="secondary" @click="logout">Sign out</button></template>
